mapper.update:
UPDATE SCM_SYS_FILE
   SET DELETED_YN = 'Y',
       LAST_UPDATED_BY = #{deletedBy},
       LAST_UPDATE_DATE = SYSTIMESTAMP
 WHERE FILE_ID = #{fileId}
   AND MNU_ID = #{mnuId}
   AND SHT_NM = #{shtNm}

mapper.select:
SELECT FILE_ID, FILE_NM, FILE_SIZE, MIME_TYPE, UPLOADED_BY, UPLOADED_AT
  FROM SCM_SYS_FILE
 WHERE MNU_ID = #{mnuId}
   AND SHT_NM = #{shtNm}
   AND DELETED_YN = 'N'
 ORDER BY UPLOADED_AT DESC
